UPDATE "City" SET "published" = 1, "intro" = 'North Shore Mahjong plays American Mahjong across the northern Chicago suburbs. Open play rotates among cafes and taverns in Highland Park and Glenview, and the club also runs Mahjong 101, advanced strategy classes and leagues for players who know the basics. Venues change from session to session, so check the address on each event.' WHERE "slug" = 'north-shore';
